UPDATE evidence_sources SET prior_expectation='Expected a lived-experience account confirming that autistic adults want lower noise and shorter reverberation, i.e. supporting a level-based requirement. The source only partly bears that out: its themes are sound sensitivity pervading life, sensory gaslighting, and AGENCY AS CRUCIAL. Agency was not in my prior expectation and is the finding that moved me toward requirement-class over level.', search_queries_used='autistic adults lived experience of noise and reverberation in buildings, qualitative interview and participatory design studies' WHERE ref_id='REF-00965';
UPDATE evidence_sources SET prior_expectation='Expected a catalogue of disabling sensory environments useful mainly for coverage. It delivered more: six principles (Sensoryscape, Space, Predictability, Understanding, Adjustments, Recovery) of which four are NOT level constructs. Prior expectation understated how much of the requirement is non-acoustic.', search_queries_used='autistic adults lived experience of noise and reverberation in buildings, qualitative interview and participatory design studies' WHERE ref_id='REF-00966';
UPDATE evidence_sources SET prior_expectation='Expected a controlled study showing ADHD adults are more disturbed by acoustic discomfort than controls, supporting a stricter threshold for this population. The result inverts the mechanism: the EEG defence response to discomfort was present in NON-ADHD participants and absent, slow or weak in ADHD participants. A stricter threshold is not the implication I expected to be able to draw.', search_queries_used='unpredictable intermittent sound and sensory load effects on attention and perceptual function for neurodivergent and brain-injured adults in indoor environments' WHERE ref_id='REF-00967';
UPDATE evidence_sources SET prior_expectation='Expected the on-parameter tier-2 anchor for reverberation and speech perception across impaired listeners. It is on-parameter but its population is predominantly NORMAL-HEARING, and its own framing is that such listeners are ROBUST to reverberation. Graded PROXY against every population this slug serves. Prior expectation was that this would be the strongest evidence in the batch; it is the weakest by population match.', search_queries_used='systematic review of reverberation time and speech perception outcomes for listeners with hearing impairment or cognitive impairment in rooms' WHERE ref_id='REF-00607';
UPDATE evidence_sources SET prior_expectation='Expected evidence that neurodivergent students need quieter study environments. Directly contradicted: Restoration is Not Silence, and imposed silence was experienced as emotionally taxing rather than restorative. This is the single source that most changed my reading of the parameter, and my prior expectation was wrong in its direction, not merely its degree.', search_queries_used='unpredictable intermittent sound and sensory load effects on attention and perceptual function for neurodivergent and brain-injured adults in indoor environments' WHERE ref_id='REF-00968';